import os

# Search for any file named calculator.py
for root, dirs, files in os.walk('.'):
    for f in files:
        if 'calculator' in f.lower():
            print(os.path.join(root, f))

# Also list all files recursively
print("--- All files ---")
for root, dirs, files in os.walk('.'):
    for f in files:
        print(os.path.join(root, f))
